// Append evidence without changing any requirement, acceptance, status or source record.
import fs from'node:fs';import path from'node:path';import assert from'node:assert/strict';import{pathToFileURL}from'node:url';import{hash,json}from'./bounded-source-hash-20261026.mjs';
export async function appendEvidence(c){const site='F:/VisibleMedicine/website',file=site+'/docs/completion-checklist.json',md=site+'/docs/completion-checklist.md',proof=c.base+'/VERIFICATION_SUMMARY.json';assert(path.resolve(c.base).startsWith(path.resolve('F:/VisibleMedicine/staging')+path.sep));assert.equal(hash(proof),c.verificationSha256);assert(json(proof).passingForStatedScope);assert(/^[a-z][a-z0-9]*$/.test(c.rootKey));const old=json(file),next=structuredClone(old),item=next.items.find(x=>x.id===c.id);assert.equal(old.revision,c.beforeRevision);assert.equal(old.items.length,71);assert.equal(item.status,c.expectedStatus);const dir=c.base+'/checklist-progress';assert(!fs.existsSync(dir));fs.mkdirSync(dir);fs.copyFileSync(file,dir+'/CHECKLIST_BEFORE.json',fs.constants.COPYFILE_EXCL);fs.copyFileSync(md,dir+'/CHECKLIST_BEFORE.md',fs.constants.COPYFILE_EXCL);const before=hash(file),{validateChecklist,renderChecklist,evidencePath}=await import(pathToFileURL(site+'/scripts/refresh-completion-checklist.mjs'));next.revision=old.revision+1;next.updatedAt=new Date().toISOString().slice(0,10);next.roots[c.rootKey]=c.base;const reference=c.rootKey+':VERIFICATION_SUMMARY.json';item.evidence.push(reference);item.completionNote=(item.completionNote??'')+' '+c.note;next.changeLog.unshift({date:next.updatedAt,revision:next.revision,change:c.change,evidence:reference});validateChecklist(next);assert.equal(next.items.filter(x=>x.scope==='optional').length,8);for(const p of old.items){const n=next.items.find(x=>x.id===p.id);if(p.id!==c.id)assert.deepEqual(n,p);else for(const k of Object.keys(p).filter(k=>!['evidence','completionNote'].includes(k)))assert.deepEqual(n[k],p[k]);}for(const k of ['baseline','importedAtlasSource','installedAtlasSource','pendingAtlasSource','unpublishedWebsiteCandidate','rules','statusDefinitions'])assert.deepEqual(next[k],old[k]);assert(fs.statSync(evidencePath(next,reference)).isFile());assert.equal(hash(file),before);fs.writeFileSync(file,JSON.stringify(next,null,2)+'\n');fs.writeFileSync(md,renderChecklist(next));const out={at:new Date().toISOString(),passing:true,revision:next.revision,changedItem:c.id,statusUnchanged:item.status,all71AndEightIdeasAndAcceptancesPreserved:true,other70AndSourceRecordsUnchanged:true,validatorAndRendererUsed:true,preimage:{path:dir+'/CHECKLIST_BEFORE.json',sha256:hash(dir+'/CHECKLIST_BEFORE.json')},after:{path:file,sha256:hash(file)},notCopiedIntoApplicationCandidate:true};fs.writeFileSync(dir+'/RESULT.json',JSON.stringify(out,null,2)+'\n',{flag:'wx'});return{path:dir+'/RESULT.json',sha256:hash(dir+'/RESULT.json'),revision:next.revision};}
